-- ===== trade-ngin migrations/014_contract_metadata_fee_per_contract.sql (trade-ngin:rpc-0b9dbf6e)
-- 014_contract_metadata_fee_per_contract.sql
--
-- Add metadata.contract_metadata."Fee Per Contract": the dollars per contract per side the
-- transaction cost model charges for a futures fill, as a column of the contract's own metadata
-- row (T-7b-2 CM1).
--
-- WHY
--
-- The cost model priced every futures fill's explicit fee with a code default of 1.50 per
-- contract (TransactionCostManager::Config, BacktestExecutionConfig, ExecutionConfig), while the
-- contract size the strategy sizes with comes from this table. HD 2026-09-25 (rulings 11 and 14):
-- one source of truth for contract specs, nothing hard-coded, costs from the metadata. After this
-- column exists the instrument registry reads it into each futures contract and the cost model
-- charges it; the code default remains only for a database without the column.
--
-- Every existing row gets the configured default fee per contract, 1.50, the reference until
-- per-row fees land (HD ruling 33, 2026-09-26), so every fill is priced exactly as before: the
-- column is number-neutral when applied. A micro or mini contract whose broker fee differs is
-- updated row by row by the migration that changes that row's contract, with its source.
--
-- The column is text, like every other column of the table; the loader converts it to a double
-- by name (PostgresDatabase::convert_metadata_to_arrow), so the loader's positional indices of
-- the older columns do not move.
--
-- SAFETY
--
--   * ADD COLUMN with a constant DEFAULT is metadata-only on PostgreSQL 11 and later: no table
--     rewrite, every existing row reads the default.
--   * NOT NULL holds from the start (every row reads '1.50'); a later INSERT that omits the
--     column gets '1.50'.
--   * No key, index, constraint or view is touched; no other column changes.
--   * Type-guarded: an existing "Fee Per Contract" of another type makes this refuse.
--   * Transactional and idempotent (ADD COLUMN IF NOT EXISTS; COMMENT repeats).
--
-- ORDER AND NUMBERING
--
-- Independent of 001-013; 014 is the next free number after 013 (T-7b-2 8b). Like 012 and 013,
-- applied to the stage-3 session clones in-session and to production only at the end-of-stage
-- merge on HD's go.
--
-- REACHABILITY
--
-- Every futures runner and backtest loads this table through InstrumentRegistry::load_instruments
-- (SELECT *). With the column present each futures contract carries its fee, and all three cost
-- managers (the backtest fills, the live fills, the PortfolioManager's optimizer cost vector)
-- charge it. The equity cost configs charge per share and never read it.

BEGIN;

DO $$
DECLARE
    t text;
BEGIN
    IF to_regclass('metadata.contract_metadata') IS NULL THEN
        RAISE EXCEPTION 'metadata.contract_metadata does not exist; this migration adds a column '
                        'to it, it does not create the table';
    END IF;
    SELECT data_type INTO t
      FROM information_schema.columns
     WHERE table_schema = 'metadata' AND table_name = 'contract_metadata'
       AND column_name = 'Fee Per Contract';
    IF t IS NOT NULL AND t <> 'text' THEN
        RAISE EXCEPTION 'metadata.contract_metadata."Fee Per Contract" already exists as %, not '
                        'text: refusing', t;
    END IF;
END $$;

ALTER TABLE metadata.contract_metadata
    ADD COLUMN IF NOT EXISTS "Fee Per Contract" TEXT NOT NULL DEFAULT '1.50';

COMMENT ON COLUMN metadata.contract_metadata."Fee Per Contract" IS
    'Dollars per contract per side that the transaction cost model charges for a fill of this '
    'contract (explicit fee: broker commission plus exchange and clearing, all-in). Every row '
    'starts at the configured default fee per contract, 1.50, the reference until per-row fees '
    'land (HD ruling 33, 2026-09-26). Read by the instrument registry by name; a database without '
    'this column prices every fill at the code default 1.50 (migration 014).';

COMMIT;

-- ===== trade-ngin migrations/017_live_results_roll_costs.sql (trade-ngin:rpc-0b9dbf6e)
-- 017_live_results_roll_costs.sql
--
-- Add trading.live_results.daily_roll_costs (numeric NOT NULL DEFAULT 0) and total_roll_costs
-- (numeric(20,8) NOT NULL DEFAULT 0): the ROLL subset of the day's and the cumulative
-- transaction costs (LOOP_SPEC v6.1 sections 6.5 and 7; T-ROLLX commit 3). The pair is the
-- SUPERSET form: daily_transaction_costs / total_transaction_costs keep their meaning (every
-- fill's cost, STRATEGY + ROLL + BORROW) and the roll columns are the part of them paid on ROLL
-- legs; the strategy-only cost is the difference. No existing read moves. The types mirror
-- daily_transaction_costs (numeric) and total_transaction_costs (numeric(20,8)).
--
-- SAFETY: ADD COLUMN with a constant DEFAULT is metadata-only; every existing row reads 0 (no
-- roll was booked before this column); no key, index or view is touched; type-guarded;
-- transactional and idempotent.

BEGIN;
DO $$
DECLARE t text;
BEGIN
    IF to_regclass('trading.live_results') IS NULL THEN RAISE EXCEPTION 'trading.live_results does not exist'; END IF;
    FOR t IN SELECT data_type FROM information_schema.columns WHERE table_schema = 'trading' AND table_name = 'live_results'
              AND column_name IN ('daily_roll_costs', 'total_roll_costs') AND data_type <> 'numeric' LOOP
        RAISE EXCEPTION 'a live_results roll cost column exists with type %, not numeric', t;
    END LOOP;
END $$;
ALTER TABLE trading.live_results ADD COLUMN IF NOT EXISTS daily_roll_costs numeric NOT NULL DEFAULT 0;
ALTER TABLE trading.live_results ADD COLUMN IF NOT EXISTS total_roll_costs numeric(20,8) NOT NULL DEFAULT 0;
COMMENT ON COLUMN trading.live_results.daily_roll_costs IS
    'The part of daily_transaction_costs paid on ROLL legs (execution_type ROLL) on this date; an upper bound (rolls trade as spreads, modelled as two outright legs). daily_transaction_costs stays the superset. LOOP_SPEC v6.1 section 6.5; migration 017.';
COMMENT ON COLUMN trading.live_results.total_roll_costs IS
    'The cumulative daily_roll_costs (the previous row''s total plus this date''s); the part of total_transaction_costs paid on ROLL legs. Migration 017.';
COMMIT;

-- ===== trade-ngin migrations/021_qt_books.sql (trade-ngin:rpc-0b9dbf6e)
-- 021_qt_books.sql
--
-- Three books side by side in every live trading table (QT platform, PR E1; master document
-- rulings 5, 9, 12, 17 and "final trading schema changes"):
--
--   system       the model's answer, written by the model run. Every row stored to date.
--   qt_proposal  what the desk asked for: seeded from system by the model run, edited in AlgoLens.
--   qt           what the engine gave back: what goes out, and what tomorrow's run starts from.
--
-- One column tells the books apart, `portfolio_type`, the column migration 001 put on
-- trading.positions and trading.equity_curve. This migration:
--
--   1. widens the portfolio_type CHECK on trading.positions and trading.equity_curve from
--      ('system','qt') to ('system','qt_proposal','qt');
--   2. adds portfolio_type TEXT NOT NULL DEFAULT 'system', with the same CHECK, to
--      trading.executions and trading.live_results, and puts it last in their keys:
--        executions_pkey                             (portfolio_id, strategy_id, strategy_name,
--                                                     date, exec_id) + portfolio_type
--        the live_results UNIQUE key                 (portfolio_id, strategy_id, date)
--                                                     + portfolio_type
--      The key constraints are found by their columns, not their names (the stage-3 scratch and
--      the test fixtures name the live_results key differently), and are re-created under the
--      name they had;
--   3. adds trading.positions.moved_by TEXT NULL: the one-pass step that moved the symbol
--      between the desk's request (qt_proposal) and what the engine gave back (qt) (ruling 12).
--      A CHECK keeps it NULL on every book but qt.
--
-- WHY THE KEYS. A qt row and a system row for the same portfolio, sleeve, date and exec id (or
-- the same portfolio, strategy and date in live_results) collide on the old keys, so the second
-- book's write fails or, worse, the first book's re-run DELETE takes the other's rows. With the
-- book last in the key the two coexist, and the engine's DELETEs are scoped by book (same PR).
-- Order ids are NOT changed: system ids stay byte-identical, and the book in the key is what
-- keeps two books' executions apart.
--
-- SAFETY
--
--   * ADD COLUMN with a constant DEFAULT is metadata-only on PostgreSQL 11+; every existing row
--     reads 'system', which is what every existing row is. No backfill.
--   * Adding a column to a key only makes it more permissive: no existing row can conflict.
--     The key rebuild re-indexes the table (executions and live_results are small: thousands of
--     rows), inside this transaction.
--   * NULL-able moved_by with no default is metadata-only; every existing row reads NULL.
--   * Guarded: refuses unless migration 001 is applied (positions/equity_curve.portfolio_type
--     exist); refuses an existing portfolio_type or moved_by of another type than text; refuses
--     when the executions primary key or the live_results unique key is not found in either its
--     pre-021 or its post-021 shape.
--   * Transactional and idempotent: a second apply changes nothing.
--
-- DEPLOY ORDERING: ship with the binary of the same commit. That binary names portfolio_type in
-- every read, write and delete of these four tables, so it fails (refuses) against a database
-- without 021; the old binary keeps working against 021 (it writes the default 'system' and its
-- DELETE predicates only ever matched system rows, the only rows a database without a desk has).
--
-- Rollback: migrations/021_qt_books_rollback.sql

BEGIN;

DO $$
DECLARE
    t   text;
    tbl text;
BEGIN
    FOREACH tbl IN ARRAY ARRAY['positions', 'equity_curve', 'executions', 'live_results'] LOOP
        IF to_regclass('trading.' || tbl) IS NULL THEN
            RAISE EXCEPTION 'trading.% does not exist; migration 021 changes it', tbl;
        END IF;
    END LOOP;
    FOREACH tbl IN ARRAY ARRAY['positions', 'equity_curve'] LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'trading'
                       AND table_name = tbl AND column_name = 'portfolio_type') THEN
            RAISE EXCEPTION 'trading.%.portfolio_type does not exist: apply migration 001 first', tbl;
        END IF;
    END LOOP;
    FOREACH tbl IN ARRAY ARRAY['executions', 'live_results'] LOOP
        SELECT data_type INTO t FROM information_schema.columns
         WHERE table_schema = 'trading' AND table_name = tbl AND column_name = 'portfolio_type';
        IF t IS NOT NULL AND t <> 'text' THEN
            RAISE EXCEPTION 'trading.%.portfolio_type exists with type %, not text', tbl, t;
        END IF;
    END LOOP;
    SELECT data_type INTO t FROM information_schema.columns
     WHERE table_schema = 'trading' AND table_name = 'positions' AND column_name = 'moved_by';
    IF t IS NOT NULL AND t <> 'text' THEN
        RAISE EXCEPTION 'trading.positions.moved_by exists with type %, not text', t;
    END IF;
END $$;

-- The key of `tbl` whose column set is exactly `cols` (contype 'p' or 'u'), or NULL.
CREATE OR REPLACE FUNCTION pg_temp.qt021_key(tbl text, cols text[]) RETURNS text
LANGUAGE sql STABLE AS $$
    SELECT c.conname::text
      FROM pg_constraint c
     WHERE c.conrelid = ('trading.' || tbl)::regclass AND c.contype IN ('p', 'u')
       AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
              FROM pg_attribute a
             WHERE a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey))
           = (SELECT array_agg(x ORDER BY x) FROM unnest(cols) x)
     LIMIT 1
$$;

DO $$
BEGIN
    IF pg_temp.qt021_key('executions', ARRAY['portfolio_id','strategy_id','strategy_name','date','exec_id']) IS NULL
       AND pg_temp.qt021_key('executions', ARRAY['portfolio_id','strategy_id','strategy_name','date','exec_id','portfolio_type']) IS NULL THEN
        RAISE EXCEPTION 'trading.executions has no key on (portfolio_id, strategy_id, strategy_name, date, exec_id[, portfolio_type]); refusing';
    END IF;
    IF pg_temp.qt021_key('live_results', ARRAY['portfolio_id','strategy_id','date']) IS NULL
       AND pg_temp.qt021_key('live_results', ARRAY['portfolio_id','strategy_id','date','portfolio_type']) IS NULL THEN
        RAISE EXCEPTION 'trading.live_results has no key on (portfolio_id, strategy_id, date[, portfolio_type]); refusing';
    END IF;
END $$;

-- 1. positions and equity_curve: widen the CHECK.
ALTER TABLE trading.positions DROP CONSTRAINT IF EXISTS positions_portfolio_type_check;
ALTER TABLE trading.positions ADD CONSTRAINT positions_portfolio_type_check
    CHECK (portfolio_type IN ('system', 'qt_proposal', 'qt'));
ALTER TABLE trading.equity_curve DROP CONSTRAINT IF EXISTS equity_curve_portfolio_type_check;
ALTER TABLE trading.equity_curve ADD CONSTRAINT equity_curve_portfolio_type_check
    CHECK (portfolio_type IN ('system', 'qt_proposal', 'qt'));

-- 2. executions and live_results: the column, its CHECK, and the key.
ALTER TABLE trading.executions ADD COLUMN IF NOT EXISTS portfolio_type TEXT NOT NULL DEFAULT 'system';
ALTER TABLE trading.executions DROP CONSTRAINT IF EXISTS executions_portfolio_type_check;
ALTER TABLE trading.executions ADD CONSTRAINT executions_portfolio_type_check
    CHECK (portfolio_type IN ('system', 'qt_proposal', 'qt'));
ALTER TABLE trading.live_results ADD COLUMN IF NOT EXISTS portfolio_type TEXT NOT NULL DEFAULT 'system';
ALTER TABLE trading.live_results DROP CONSTRAINT IF EXISTS live_results_portfolio_type_check;
ALTER TABLE trading.live_results ADD CONSTRAINT live_results_portfolio_type_check
    CHECK (portfolio_type IN ('system', 'qt_proposal', 'qt'));

DO $$
DECLARE k text;
BEGIN
    k := pg_temp.qt021_key('executions', ARRAY['portfolio_id','strategy_id','strategy_name','date','exec_id']);
    IF k IS NOT NULL THEN
        EXECUTE format('ALTER TABLE trading.executions DROP CONSTRAINT %I', k);
        EXECUTE format('ALTER TABLE trading.executions ADD CONSTRAINT %I PRIMARY KEY '
                       '(portfolio_id, strategy_id, strategy_name, date, exec_id, portfolio_type)', k);
    END IF;
    k := pg_temp.qt021_key('live_results', ARRAY['portfolio_id','strategy_id','date']);
    IF k IS NOT NULL THEN
        EXECUTE format('ALTER TABLE trading.live_results DROP CONSTRAINT %I', k);
        EXECUTE format('ALTER TABLE trading.live_results ADD CONSTRAINT %I UNIQUE '
                       '(portfolio_id, strategy_id, date, portfolio_type)', k);
    END IF;
END $$;

-- 3. positions.moved_by.
ALTER TABLE trading.positions ADD COLUMN IF NOT EXISTS moved_by TEXT;
ALTER TABLE trading.positions DROP CONSTRAINT IF EXISTS positions_moved_by_qt_only;
ALTER TABLE trading.positions ADD CONSTRAINT positions_moved_by_qt_only
    CHECK (moved_by IS NULL OR portfolio_type = 'qt');

COMMENT ON COLUMN trading.executions.portfolio_type IS
    'The book the fill belongs to: system (the model run), qt_proposal (the desk''s request) or qt (what the engine gave back and what goes out). Part of executions_pkey. Every row before migration 021 is system.';
COMMENT ON COLUMN trading.live_results.portfolio_type IS
    'The book the row belongs to: system, qt_proposal or qt (as trading.positions.portfolio_type). Part of the (portfolio_id, strategy_id, date, portfolio_type) key. Every row before migration 021 is system.';
COMMENT ON COLUMN trading.positions.moved_by IS
    'qt rows only: the one-pass step that moved the symbol from the desk''s request (the qt_proposal row) to what the engine gave back (this row); NULL when nothing moved it. NULL on every system and qt_proposal row (CHECK positions_moved_by_qt_only). Ruling 12; migration 021.';

COMMIT;

-- ===== trade-ngin migrations/022_strategy_config.sql (trade-ngin:rpc-0b9dbf6e)
-- 022_strategy_config.sql
--
-- Desk settings from the database (QT plan E2; rulings 2, 3, 4, 24, 26).
--
-- 1. trading.strategy_config: the ONE new table of the settings lane. One row per desk change to
--    a portfolio's settings, versioned and append-only. `overrides` is a JSON object in the shape
--    of the portfolio's merged config files (defaults.json + portfolio.json, with risk.json under
--    "risk"), deep-merged on top of the files at the start of a LIVE run only (ruling 4: backtests
--    keep the file config). At most one row per portfolio is active (partial unique index); with
--    no active row the run uses its files unchanged. A change states its reason and its author.
--    The engine refuses a run whose active row cannot be applied (ruling 24) and never falls back
--    to the files; the checks it makes (no null, no credential/database/email key, no key the
--    files do not hold) are in ConfigLoader, not here.
--
-- 2. trading.live_run_metadata gains:
--      settings_used jsonb  the credential-free effective config the run traded on, as
--                           {"strategy_config_version": <n or null>, "config": {...}};
--                           written by every live run of a binary from this migration on;
--      published_by text, published_at timestamptz  the desk publish record (QT plan E8, ruling
--                           18); added here so the table changes once. NULL until E8 writes them.
--    Rows written before this migration read NULL in all three.
--
-- Ported from PR #60's migration 008 (strategy_config DDL only; its config_manifest table is NOT
-- created: ruling 26 puts the settings used on live_run_metadata). created_by is text here (#60
-- had integer): AlgoLens records the author's login.
--
-- SAFETY: CREATE TABLE / ADD COLUMN of NULL-able columns with no default are metadata-only; no
-- existing row, key, index or view of live_run_metadata is touched; type-guarded (an existing
-- strategy_config or column of another shape makes 022 refuse); transactional and idempotent.

BEGIN;
DO $$
DECLARE bad text;
BEGIN
    IF to_regclass('trading.live_run_metadata') IS NULL THEN
        RAISE EXCEPTION 'trading.live_run_metadata does not exist';
    END IF;
    -- A strategy_config left by another branch (PR #60's 008 had created_by integer and no
    -- object check) must not be taken for this one.
    IF to_regclass('trading.strategy_config') IS NOT NULL THEN
        FOR bad IN
            SELECT e.col || ' expected ' || e.typ || ' got ' || coalesce(c.data_type, 'nothing')
              FROM (VALUES ('id', 'bigint'), ('portfolio_id', 'text'), ('version', 'integer'),
                           ('overrides', 'jsonb'), ('reason', 'text'), ('created_by', 'text'),
                           ('created_at', 'timestamp with time zone'), ('is_active', 'boolean')) e(col, typ)
              LEFT JOIN information_schema.columns c
                ON c.table_schema = 'trading' AND c.table_name = 'strategy_config' AND c.column_name = e.col
             WHERE c.data_type IS DISTINCT FROM e.typ
        LOOP
            RAISE EXCEPTION 'trading.strategy_config exists with another shape: %', bad;
        END LOOP;
    END IF;
    FOR bad IN
        SELECT column_name || ' ' || data_type FROM information_schema.columns
         WHERE table_schema = 'trading' AND table_name = 'live_run_metadata'
           AND ((column_name = 'settings_used' AND data_type <> 'jsonb')
             OR (column_name = 'published_by' AND data_type <> 'text')
             OR (column_name = 'published_at' AND data_type <> 'timestamp with time zone'))
    LOOP
        RAISE EXCEPTION 'trading.live_run_metadata has a column of another type: %', bad;
    END LOOP;
END $$;

CREATE TABLE IF NOT EXISTS trading.strategy_config (
    id            bigserial   PRIMARY KEY,
    portfolio_id  text        NOT NULL,
    version       integer     NOT NULL,
    overrides     jsonb       NOT NULL,
    reason        text        NOT NULL,
    created_by    text        NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    is_active     boolean     NOT NULL DEFAULT false,
    CONSTRAINT strategy_config_portfolio_version_key UNIQUE (portfolio_id, version),
    CONSTRAINT strategy_config_version_positive CHECK (version > 0),
    CONSTRAINT strategy_config_overrides_object CHECK (jsonb_typeof(overrides) = 'object'),
    CONSTRAINT strategy_config_reason_not_empty CHECK (length(btrim(reason)) > 0),
    CONSTRAINT strategy_config_created_by_not_empty CHECK (length(btrim(created_by)) > 0)
);

-- At most one active version per portfolio: two active rows would be worse than no versioning.
CREATE UNIQUE INDEX IF NOT EXISTS strategy_config_one_active_per_portfolio
    ON trading.strategy_config (portfolio_id) WHERE is_active;

COMMENT ON TABLE trading.strategy_config IS
    'Desk settings changes, one versioned row per change, at most one active per portfolio. overrides is deep-merged over the portfolio''s config files at the start of a live run only; a row that cannot be applied refuses the run (ruling 24). QT plan E2; migration 022.';
COMMENT ON COLUMN trading.strategy_config.overrides IS
    'A JSON object in the shape of the merged config files (defaults.json + portfolio.json, risk.json under "risk"). Every key must exist in the files; no null; no database, email, portfolio_id or credential key. Arrays replace the file''s array whole.';

ALTER TABLE trading.live_run_metadata ADD COLUMN IF NOT EXISTS settings_used jsonb;
ALTER TABLE trading.live_run_metadata ADD COLUMN IF NOT EXISTS published_by text;
ALTER TABLE trading.live_run_metadata ADD COLUMN IF NOT EXISTS published_at timestamptz;

COMMENT ON COLUMN trading.live_run_metadata.settings_used IS
    'The credential-free effective config the run traded on: {"strategy_config_version": n or null (files only), "config": the merged files plus the active strategy_config overrides, without the database and email sections}. NULL on rows written before migration 022''s binary. QT plan E2; migration 022.';
COMMENT ON COLUMN trading.live_run_metadata.published_by IS
    'Who published the day''s desk book (QT plan E8). NULL until published. Migration 022.';
COMMENT ON COLUMN trading.live_run_metadata.published_at IS
    'When the day''s desk book was published (QT plan E8). NULL until published. Migration 022.';
COMMIT;

-- ===== trade-ngin migrations/023_qt_command_log.sql (trade-ngin:rpc-0b9dbf6e)
-- 023_qt_command_log.sql
--
-- The QT platform's command log and the remaining schema of docs/design/qt-contract.md (sections 2,
-- 4 and 5). Applied after 021 (books) and 022 (strategy_config).
--
--   1. trading.position_overrides is rebuilt as the desk's command log: one row per save, override
--      request, override decision and publish, keyed by portfolio and book date. AlgoLens inserts
--      rows; the engine (desk-agent) moves status/result. Rows are never deleted, and only the
--      engine-owned columns may change (trigger). The old #55 shape had no portfolio or date and an
--      UPDATE ... DO INSTEAD NOTHING rule that made recording a decision impossible; it holds 0 rows
--      on new_algo_data (checked 2026-10-09) and this migration refuses if any row exists.
--   2. trading.live_results.book_source: which path produced a qt row (model, desk, override).
--      Master doc ruling 9: each day's record says which happened.
--   3. trading.strategy_registry.portfolio_group and desk_editable (ruling 20 and section 2 of the
--      contract), and the two QT portfolios.
--
-- The ruling-28 drops (risk_limits, portfolios, strategy_book_memberships, portfolio_assignments)
-- are in 024, applied separately.
--
-- SAFETY: transactional; refuses on a non-empty position_overrides; otherwise additive.

BEGIN;

DO $$
BEGIN
    IF to_regclass('trading.live_results') IS NULL THEN RAISE EXCEPTION 'trading.live_results does not exist'; END IF;
    IF to_regclass('trading.strategy_registry') IS NULL THEN RAISE EXCEPTION 'trading.strategy_registry does not exist'; END IF;
    IF to_regclass('trading.position_overrides') IS NOT NULL THEN
        IF EXISTS (SELECT 1 FROM trading.position_overrides) THEN
            RAISE EXCEPTION 'trading.position_overrides holds rows; 023 rebuilds it and refuses to discard them';
        END IF;
    END IF;
END $$;

-- 1. The command log.
DROP TABLE IF EXISTS trading.position_overrides CASCADE;

CREATE TABLE trading.position_overrides (
    id               bigserial PRIMARY KEY,
    portfolio_id     text        NOT NULL,
    date             date        NOT NULL,
    kind             text        NOT NULL CHECK (kind IN ('save', 'override_request', 'override_decision', 'publish')),
    status           text        NOT NULL DEFAULT 'pending'
                                 CHECK (status IN ('pending', 'running', 'done', 'refused', 'failed')),
    requested_by     text        NOT NULL CHECK (length(btrim(requested_by)) > 0),
    reason           text,
    payload          jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(payload) = 'object'),
    parent_id        bigint      REFERENCES trading.position_overrides (id),
    approver_role    text        CHECK (approver_role IN ('vp', 'president')),
    token_hash       text,
    token_expires_at timestamptz,
    result           jsonb,
    message          text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    started_at       timestamptz,
    finished_at      timestamptz,
    CONSTRAINT position_overrides_reason_required
        CHECK (kind NOT IN ('save', 'override_request') OR length(btrim(coalesce(reason, ''))) > 0),
    CONSTRAINT position_overrides_decision_shape
        CHECK (kind <> 'override_decision' OR (parent_id IS NOT NULL AND approver_role IS NOT NULL))
);

CREATE INDEX position_overrides_portfolio_date_kind ON trading.position_overrides (portfolio_id, date, kind);
CREATE INDEX position_overrides_pending ON trading.position_overrides (status) WHERE status IN ('pending', 'running');
CREATE UNIQUE INDEX position_overrides_one_publish
    ON trading.position_overrides (portfolio_id, date) WHERE kind = 'publish' AND status = 'done';
CREATE UNIQUE INDEX position_overrides_token ON trading.position_overrides (token_hash) WHERE token_hash IS NOT NULL;

COMMENT ON TABLE trading.position_overrides IS
    'QT desk command log (docs/design/qt-contract.md section 4): one row per save, override request, override decision and publish. AlgoLens inserts; the engine moves status, started_at, finished_at, result and message. Never deleted. Migration 023.';

CREATE OR REPLACE FUNCTION trading.position_overrides_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'trading.position_overrides rows are never deleted';
    END IF;
    -- Only the engine-owned columns (and token_hash being cleared once used) may change.
    IF (NEW.id, NEW.portfolio_id, NEW.date, NEW.kind, NEW.requested_by, NEW.reason, NEW.payload,
        NEW.parent_id, NEW.approver_role, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.portfolio_id, OLD.date, OLD.kind, OLD.requested_by, OLD.reason, OLD.payload,
        OLD.parent_id, OLD.approver_role, OLD.created_at) THEN
        RAISE EXCEPTION 'trading.position_overrides: only status, result, message, started_at, finished_at and the token may change';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER position_overrides_guard
    BEFORE UPDATE OR DELETE ON trading.position_overrides
    FOR EACH ROW EXECUTE FUNCTION trading.position_overrides_guard();

-- 2. Which path produced a book's day.
ALTER TABLE trading.live_results ADD COLUMN IF NOT EXISTS book_source text;
ALTER TABLE trading.live_results DROP CONSTRAINT IF EXISTS live_results_book_source_check;
ALTER TABLE trading.live_results ADD CONSTRAINT live_results_book_source_check
    CHECK (book_source IS NULL OR book_source IN ('model', 'desk', 'override'));
COMMENT ON COLUMN trading.live_results.book_source IS
    'For a qt row: model (no desk save that day, qt = the model result), desk (the one pass ran on the desk proposal) or override (an approved override booked the proposal exactly). NULL on system rows. Migration 023.';

-- 3. Registry grouping and desk editing, and the two QT portfolios.
ALTER TABLE trading.strategy_registry ADD COLUMN IF NOT EXISTS portfolio_group text;
ALTER TABLE trading.strategy_registry ADD COLUMN IF NOT EXISTS desk_editable boolean NOT NULL DEFAULT false;

INSERT INTO trading.strategy_registry
    (id, strategy_type, portfolio_id, name, description, initial_equity, managers, is_active, sort_order,
     lifecycle, portfolio_group, desk_editable)
VALUES
    ('qt_conservative', 'LIVE_TREND_FOLLOWING', 'QT_CONSERVATIVE_PORTFOLIO', 'QT Trend Following',
     'Conservative trend following, desk-edited by the QT desk', 500000, '["QT desk"]'::jsonb, true, 10,
     'live', 'qt_conservative', true),
    ('qt_conservative_model', 'LIVE_TREND_FOLLOWING', 'QT_CONSERVATIVE_MODEL_PORTFOLIO', 'QT Trend Following (model)',
     'The same strategy and capital with desk editing off: the untouched model book', 500000, '["AlgoLens System"]'::jsonb, true, 11,
     'live', 'qt_conservative', false)
ON CONFLICT (id) DO NOTHING;


COMMIT;

-- ===== trade-ngin migrations/024_drop_retired_qt_tables.sql (trade-ngin:rpc-0b9dbf6e)
-- 024_drop_retired_qt_tables.sql
--
-- Ruling 28 (QT master document, 2026-10-08): drop the tables added to production outside merged
-- PRs that the design does not use: trading.risk_limits (#56's published limits; its only reader,
-- the AlgoLens pre-check, is gone), and the preview books registry trading.portfolios,
-- trading.strategy_book_memberships and trading.portfolio_assignments (strategy_registry carries
-- the grouping instead, migration 023). Nothing on main in trade-ngin or AlgoLens reads them, and no
-- foreign key points at them (checked on new_algo_data 2026-10-09: rows 0, 0, 4, 0).
--
-- Irreversible: there is no rollback file. The pre-QT backup on the trade-ngin host,
-- /home/ubuntu/backups/new_algo_data_trading_metadata_backtest_pre_qt_20261009T0225Z.dump,
-- holds their definitions and data (pg_restore -t <table>).

BEGIN;
DROP TABLE IF EXISTS trading.portfolio_assignments;
DROP TABLE IF EXISTS trading.strategy_book_memberships;
DROP TABLE IF EXISTS trading.portfolios;
DROP TABLE IF EXISTS trading.risk_limits;
COMMIT;

-- ===== trade-ngin migrations/025_qt_command_log_hardening.sql (trade-ngin:rpc-0b9dbf6e)
-- 025_qt_command_log_hardening.sql
--
-- QT hardening (2026-10-09; docs/design/qt-contract.md C2 and C4, and the grants review). Applied
-- after 023 (and 024). Transactional; refuses when existing rows would break the new indexes.
--
--   1. One decision per request, one open publish and one open override request per day (C2):
--      unique partial indexes on trading.position_overrides.
--        - override_decision: one per parent_id while pending, running or done (a refused or
--          failed decision does not count, so the request can still be decided).
--        - publish: one per (portfolio_id, date) while pending or running (023 already allows
--          one done publish per day).
--        - override_request: one per (portfolio_id, date) while pending or running. "Done, not
--          yet decided and not expired" depends on other rows and on now(), which no index can
--          express: AlgoLens enforces that part under its lock.
--   2. The command row life cycle (C4), by trigger:
--        - an INSERT must be 'pending' with started_at, finished_at, result, message, token_hash
--          and token_expires_at NULL;
--        - status moves pending -> running, running -> done | refused | failed, and
--          running -> pending only inside a transaction that set algogators.recovery = 'on'
--          (the desk service's recovery of a stale or orphaned row, command_store.requeue);
--        - a terminal row (done, refused, failed) is final: any UPDATE of it is refused;
--        - TRUNCATE is refused (statement trigger), as DELETE already is (023).
--      The 023 guard function is replaced in place (same trigger), keeping its column rule.
--   3. Grants.
--        - trading.live_run_metadata and its id sequence: PUBLIC had every privilege
--          (arwdDxt on the table, rU on the sequence). The roles that use the table keep
--          explicit grants (granted here first, idempotently, where the role exists); then
--          PUBLIC loses everything. Checked on new_algo_data 2026-10-09: fund_member,
--          quant_dev, quant_research_ro, leadership_ro and investor_relations_ro keep SELECT;
--          quant_dev_rw, quant_trading_rw (svc_trade_ngin, qt_engine_app), leadership_rw and
--          svc_algolens (qt_algolens_app) keep SELECT, INSERT, UPDATE, DELETE and the sequence.
--          svc_airflow and svc_data_ngin have no USAGE on schema trading, so PUBLIC gave them
--          nothing. postgres (owner, superuser) is unaffected.
--        - trading.position_overrides: svc_algolens loses UPDATE, DELETE and TRUNCATE; it keeps
--          SELECT, INSERT and USAGE on the id sequence (granted explicitly). AlgoLens never
--          updates a command row and, since AlgoLens #116, takes no FOR UPDATE lock on one.
--          svc_trade_ngin (the engine and the desk service) gets SELECT, INSERT, UPDATE and
--          DELETE explicitly (it already has them through quant_trading_rw; DELETE stays
--          refused by the 023 trigger).
--      Compatible with AlgoLens' emulation (algolens-api/tests/fixtures/sql/025_emulated.sql):
--      same index names and predicates, same insert rule, same transitions (the recovery move
--      additionally needs algogators.recovery = 'on'), same truncate block.
--
-- Not done here, on purpose: SET NOT NULL on position_overrides or live_run_metadata columns
-- that hold NULLs today (the spec leaves them; see migrations/README.md).

BEGIN;

DO $$
DECLARE
    dup text;
BEGIN
    IF to_regclass('trading.position_overrides') IS NULL THEN
        RAISE EXCEPTION 'trading.position_overrides does not exist (apply 023 first)';
    END IF;
    IF to_regprocedure('trading.position_overrides_guard()') IS NULL THEN
        RAISE EXCEPTION 'trading.position_overrides_guard() does not exist (apply 023 first)';
    END IF;
    IF to_regclass('trading.live_run_metadata') IS NULL THEN
        RAISE EXCEPTION 'trading.live_run_metadata does not exist';
    END IF;

    SELECT string_agg(parent_id::text, ', ') INTO dup FROM (
        SELECT parent_id FROM trading.position_overrides
        WHERE kind = 'override_decision' AND status IN ('pending', 'running', 'done')
        GROUP BY parent_id HAVING count(*) > 1) d;
    IF dup IS NOT NULL THEN
        RAISE EXCEPTION 'override requests with more than one live or done decision: %; resolve them first', dup;
    END IF;
    SELECT string_agg(portfolio_id || ' ' || date, ', ') INTO dup FROM (
        SELECT portfolio_id, date FROM trading.position_overrides
        WHERE kind = 'publish' AND status IN ('pending', 'running')
        GROUP BY portfolio_id, date HAVING count(*) > 1) d;
    IF dup IS NOT NULL THEN
        RAISE EXCEPTION 'days with more than one open publish: %; resolve them first', dup;
    END IF;
    SELECT string_agg(portfolio_id || ' ' || date, ', ') INTO dup FROM (
        SELECT portfolio_id, date FROM trading.position_overrides
        WHERE kind = 'override_request' AND status IN ('pending', 'running')
        GROUP BY portfolio_id, date HAVING count(*) > 1) d;
    IF dup IS NOT NULL THEN
        RAISE EXCEPTION 'days with more than one open override request: %; resolve them first', dup;
    END IF;
END $$;

-- 1. C2 indexes.
CREATE UNIQUE INDEX IF NOT EXISTS position_overrides_one_decision
    ON trading.position_overrides (parent_id)
    WHERE kind = 'override_decision' AND status IN ('pending', 'running', 'done');
CREATE UNIQUE INDEX IF NOT EXISTS position_overrides_one_open_publish
    ON trading.position_overrides (portfolio_id, date)
    WHERE kind = 'publish' AND status IN ('pending', 'running');
CREATE UNIQUE INDEX IF NOT EXISTS position_overrides_one_open_request
    ON trading.position_overrides (portfolio_id, date)
    WHERE kind = 'override_request' AND status IN ('pending', 'running');

-- 2. C4 life cycle.
CREATE OR REPLACE FUNCTION trading.position_overrides_insert_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status IS DISTINCT FROM 'pending'
       OR NEW.started_at IS NOT NULL OR NEW.finished_at IS NOT NULL
       OR NEW.result IS NOT NULL OR NEW.message IS NOT NULL
       OR NEW.token_hash IS NOT NULL OR NEW.token_expires_at IS NOT NULL THEN
        RAISE EXCEPTION 'trading.position_overrides: a new row must be pending, with started_at, finished_at, result, message and the token NULL';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS position_overrides_insert_guard ON trading.position_overrides;
CREATE TRIGGER position_overrides_insert_guard
    BEFORE INSERT ON trading.position_overrides
    FOR EACH ROW EXECUTE FUNCTION trading.position_overrides_insert_guard();

CREATE OR REPLACE FUNCTION trading.position_overrides_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'trading.position_overrides rows are never deleted';
    END IF;
    -- 023: only the engine-owned columns (and token_hash being cleared once used) may change.
    IF (NEW.id, NEW.portfolio_id, NEW.date, NEW.kind, NEW.requested_by, NEW.reason, NEW.payload,
        NEW.parent_id, NEW.approver_role, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.portfolio_id, OLD.date, OLD.kind, OLD.requested_by, OLD.reason, OLD.payload,
        OLD.parent_id, OLD.approver_role, OLD.created_at) THEN
        RAISE EXCEPTION 'trading.position_overrides: only status, result, message, started_at, finished_at and the token may change';
    END IF;
    -- 025 (C4): terminal rows are final; status moves only forward, or back to pending by recovery.
    IF OLD.status IN ('done', 'refused', 'failed') THEN
        RAISE EXCEPTION 'trading.position_overrides row % is % and final; insert a new row to retry', OLD.id, OLD.status;
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF OLD.status = 'pending' AND NEW.status = 'running' THEN
            NULL;
        ELSIF OLD.status = 'running' AND NEW.status IN ('done', 'refused', 'failed') THEN
            NULL;
        ELSIF OLD.status = 'running' AND NEW.status = 'pending'
              AND current_setting('algogators.recovery', true) = 'on' THEN
            NULL;
        ELSE
            RAISE EXCEPTION 'trading.position_overrides row %: % -> % is not an allowed status change', OLD.id, OLD.status, NEW.status;
        END IF;
    END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION trading.position_overrides_no_truncate() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'trading.position_overrides is never truncated';
END $$;

DROP TRIGGER IF EXISTS position_overrides_no_truncate ON trading.position_overrides;
CREATE TRIGGER position_overrides_no_truncate
    BEFORE TRUNCATE ON trading.position_overrides
    FOR EACH STATEMENT EXECUTE FUNCTION trading.position_overrides_no_truncate();

-- 3. Grants. Explicit grants first, for every role that exists, then PUBLIC goes.
DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['fund_member', 'quant_dev', 'quant_research_ro', 'leadership_ro',
                             'investor_relations_ro'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT SELECT ON trading.live_run_metadata TO %I', r);
        END IF;
    END LOOP;
    FOREACH r IN ARRAY ARRAY['quant_dev_rw', 'quant_trading_rw', 'leadership_rw', 'svc_algolens',
                             'svc_trade_ngin'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON trading.live_run_metadata TO %I', r);
            EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE trading.live_run_metadata_id_seq TO %I', r);
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_algolens') THEN
        GRANT SELECT, INSERT ON trading.position_overrides TO svc_algolens;
        GRANT USAGE, SELECT ON SEQUENCE trading.position_overrides_id_seq TO svc_algolens;
        REVOKE UPDATE, DELETE, TRUNCATE ON trading.position_overrides FROM svc_algolens;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_trade_ngin') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON trading.position_overrides TO svc_trade_ngin;
        GRANT USAGE, SELECT ON SEQUENCE trading.position_overrides_id_seq TO svc_trade_ngin;
    END IF;
END $$;

REVOKE ALL ON trading.live_run_metadata FROM PUBLIC;
REVOKE ALL ON SEQUENCE trading.live_run_metadata_id_seq FROM PUBLIC;

COMMENT ON TABLE trading.position_overrides IS
    'QT desk command log (docs/design/qt-contract.md section 4): one row per save, override request, override decision and publish. AlgoLens inserts pending rows; the engine moves status, started_at, finished_at, result and message (pending -> running -> done/refused/failed; running -> pending only by the agent''s recovery). Terminal rows are final. Never deleted or truncated. Migrations 023, 025.';

COMMIT;

-- ===== trade-ngin migrations/027_qt_daily_cutoff.sql (trade-ngin:rpc-0b9dbf6e)
-- 027_qt_daily_cutoff.sql
--
-- The QT daily cutoff (decided 2026-10-09; docs/design/qt-contract.md C7, amending rulings 18
-- and 29). Applied after 022 and 025. Additive and transactional; re-applying it is a no-op.
--
--   1. trading.live_run_metadata gains the day's approval and send state:
--        - publish_source text NULL, CHECK (publish_source IN ('desk', 'fallback', 'model-only')):
--          who published the day. 'desk' = the desk's approval (the Publish command, "Approve"
--          in AlgoLens); 'fallback' = the 10:00 fallback or the catch-up of a missed past day
--          (qt reset to the model's book); 'model-only' = the untouched model twin.
--        - sent_at timestamptz NULL: when the day's e-mail went out (set once, by the engine).
--      published_by and published_at (022) are kept. Rows published before 027 keep NULL in
--      both columns: their source is not known, and an e-mail they sent is still found in the
--      publish row's result.email_sent_at (the engine checks both and never sends twice).
--   2. Grants, as 025 set them: svc_trade_ngin (the engine and the desk service) reads and writes
--      the two columns (it already holds SELECT, INSERT, UPDATE, DELETE on the table; granted
--      again here, idempotently). svc_algolens (qt_algolens_app) only reads them: its table-wide
--      INSERT and UPDATE become column grants on every OTHER column, so everything it could
--      write before it still can, and it cannot write publish_source or sent_at. Other roles are
--      unchanged (the table-wide grants 025 made cover the new columns: readers read, the *_rw
--      roles write).

BEGIN;

DO $$
DECLARE
    bad text;
BEGIN
    IF to_regclass('trading.live_run_metadata') IS NULL THEN
        RAISE EXCEPTION 'trading.live_run_metadata does not exist';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'trading'
                   AND table_name = 'live_run_metadata' AND column_name = 'published_at') THEN
        RAISE EXCEPTION 'trading.live_run_metadata has no published_at (apply 022 first)';
    END IF;
    SELECT string_agg(column_name || ' ' || data_type, ', ') INTO bad
    FROM information_schema.columns
    WHERE table_schema = 'trading' AND table_name = 'live_run_metadata'
      AND ((column_name = 'publish_source' AND data_type <> 'text')
        OR (column_name = 'sent_at' AND data_type <> 'timestamp with time zone'));
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'trading.live_run_metadata has a column of another type: %', bad;
    END IF;
END $$;

-- 1. The columns.
ALTER TABLE trading.live_run_metadata ADD COLUMN IF NOT EXISTS publish_source text;
ALTER TABLE trading.live_run_metadata ADD COLUMN IF NOT EXISTS sent_at timestamptz;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'live_run_metadata_publish_source_check'
                     AND conrelid = 'trading.live_run_metadata'::regclass) THEN
        ALTER TABLE trading.live_run_metadata ADD CONSTRAINT live_run_metadata_publish_source_check
            CHECK (publish_source IN ('desk', 'fallback', 'model-only'));
    END IF;
END $$;

COMMENT ON COLUMN trading.live_run_metadata.publish_source IS
    'QT contract C7: who published the day: desk (the desk''s approval), fallback (the 10:00 fallback, or the catch-up of a missed past day: the model''s book), model-only (the model twin). NULL: unpublished, or published before migration 027.';
COMMENT ON COLUMN trading.live_run_metadata.sent_at IS
    'QT contract C7: when the day''s daily e-mail and CSV went out (set once by the engine). NULL: not sent (not yet, a past day caught up, or e-mail disabled).';

-- 2. Grants.
DO $$
DECLARE
    others text;
    priv text;
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_trade_ngin') THEN
        GRANT SELECT, INSERT, UPDATE ON trading.live_run_metadata TO svc_trade_ngin;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_algolens') THEN
        SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position) INTO others
        FROM information_schema.columns
        WHERE table_schema = 'trading' AND table_name = 'live_run_metadata'
          AND column_name NOT IN ('publish_source', 'sent_at');
        GRANT SELECT ON trading.live_run_metadata TO svc_algolens;
        FOREACH priv IN ARRAY ARRAY['INSERT', 'UPDATE'] LOOP
            -- Only a table-wide grant held directly is narrowed (re-applying finds none). A
            -- table-wide REVOKE also drops the role's column grants, so it goes first.
            IF EXISTS (SELECT 1 FROM information_schema.role_table_grants
                       WHERE grantee = 'svc_algolens' AND table_schema = 'trading'
                         AND table_name = 'live_run_metadata' AND privilege_type = priv) THEN
                EXECUTE format('REVOKE %s ON trading.live_run_metadata FROM svc_algolens', priv);
                EXECUTE format('GRANT %s (%s) ON trading.live_run_metadata TO svc_algolens',
                               priv, others);
            END IF;
        END LOOP;
    END IF;
END $$;

COMMIT;

-- ===== trade-ngin migrations/028_ops_data_ready.sql (trade-ngin:rpc-0b9dbf6e)
-- 028_ops_data_ready.sql
--
-- Data readiness for the QT data-driven run (interim design of
-- https://github.com/AlgoGators/trade-ngin/issues/191; #192 later carries the same rows over
-- NATS). Additive, transactional and idempotent: re-applying it is a no-op.
--
--   1. Schema ops and table ops.data_ready: one row per (dataset, bar_date), written by data-ngin
--      when its pull of that dataset for that bar date finishes (04:30 ET: the vendor's
--      historical data is ~8 h delayed, so bar D is pulled early on D+1). An upsert: a re-pull
--      rewrites the row and moves finished_at, which makes the engine-rpc scheduler rebuild the
--      next trading day's books once more. status: complete (every expected symbol loaded), partial
--      (missing names the symbols, as futures_data.ohlcv_1d.symbol spells them), failed.
--      The scheduler reads dataset 'futures_ohlcv_1d'.
--   2. Grants:
--        - qt_engine_app and svc_trade_ngin (the engine and its desk service): USAGE on ops,
--          SELECT on ops.data_ready. They never write it.
--        - postgres (data-ngin connects as postgres today): SELECT, INSERT, UPDATE. A superuser
--          needs none of this; it is written down so the grant moves with data-ngin when it gets
--          its own role (svc_data_ngin: grant the same three then).
--      Roles that do not exist on the server are skipped.
--
-- Apply (as postgres, on new_algo_data):
--     psql -X -v ON_ERROR_STOP=1 -d new_algo_data -f migrations/028_ops_data_ready.sql

BEGIN;

DO $$
DECLARE
    bad text;
BEGIN
    IF to_regclass('ops.data_ready') IS NULL THEN
        RETURN;
    END IF;
    -- Re-applied over a table of another shape: refuse instead of silently keeping it.
    SELECT string_agg(c, ', ') INTO bad
    FROM unnest(ARRAY['dataset', 'bar_date', 'expected', 'loaded', 'missing', 'status', 'run_id',
                      'finished_at']) AS c
    WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns
                      WHERE table_schema = 'ops' AND table_name = 'data_ready'
                        AND column_name = c);
    IF bad IS NOT NULL THEN
        RAISE EXCEPTION 'ops.data_ready exists without the column(s): %', bad;
    END IF;
END $$;

CREATE SCHEMA IF NOT EXISTS ops;

CREATE TABLE IF NOT EXISTS ops.data_ready (
    dataset     text        NOT NULL,
    bar_date    date        NOT NULL,
    expected    int         NOT NULL,
    loaded      int         NOT NULL,
    missing     text[]      NOT NULL DEFAULT '{}',
    status      text        NOT NULL CHECK (status IN ('complete', 'partial', 'failed')),
    run_id      text,
    finished_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (dataset, bar_date)
);

COMMENT ON SCHEMA ops IS
    'Operational state shared between the AlgoGators services (migration 028).';
COMMENT ON TABLE ops.data_ready IS
    'Migration 028 (issue #191): data-ngin''s pull of a dataset for a bar date is done. Upserted by data-ngin; read by the engine-rpc scheduler, which builds the next trading day''s QT books once per finished_at.';
COMMENT ON COLUMN ops.data_ready.missing IS
    'Symbols expected but not loaded (futures_data.ohlcv_1d.symbol spelling); empty when complete.';
COMMENT ON COLUMN ops.data_ready.finished_at IS
    'When the pull finished. A re-pull moves it, and the scheduler rebuilds the unpublished target day.';

DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['qt_engine_app', 'svc_trade_ngin'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT USAGE ON SCHEMA ops TO %I', r);
            EXECUTE format('GRANT SELECT ON ops.data_ready TO %I', r);
        END IF;
    END LOOP;
    -- data-ngin (connects as postgres today).
    GRANT USAGE ON SCHEMA ops TO postgres;
    GRANT SELECT, INSERT, UPDATE ON ops.data_ready TO postgres;
END $$;

COMMIT;

-- ===== trade-ngin migrations/029_qt_rescind.sql (trade-ngin:rpc-0b9dbf6e)
-- 029_qt_rescind.sql
--
-- Rescind (decided by Dom 2026-10-13; docs/design/qt-contract.md C8): the desk takes back its
-- own approval before the 09:30 send. Applied after 023, 025 and 027. Transactional; re-applying
-- it is a no-op.
--
--   1. trading.position_overrides.kind gains 'rescind': the command AlgoLens writes for "Rescind
--      approval" (desk.proto 1.2.0 Rescind). The engine clears published_by, published_at and
--      publish_source on the day's live_run_metadata rows and records the approval it took back
--      in the row's result.
--   2. position_overrides_one_publish (023: at most one done publish row per portfolio and day)
--      is dropped. A rescinded approval leaves its publish row done (C4: terminal rows are
--      final), so the day's next approval is a second done publish row. live_run_metadata
--      published_at, checked under the day lock by AlgoLens and by the engine, is what keeps a
--      day from being approved twice (C3), as it already was. The open-publish index
--      (position_overrides_one_open_publish, 025) stays.
--   3. position_overrides_one_open_rescind: at most one pending or running rescind per
--      portfolio and day, as for publish and override requests (C2).
--
-- No grant changes: svc_algolens already inserts command rows and svc_trade_ngin already writes
-- live_run_metadata.

BEGIN;

DO $$
BEGIN
    IF to_regclass('trading.position_overrides') IS NULL THEN
        RAISE EXCEPTION 'trading.position_overrides does not exist (apply 023 first)';
    END IF;
    IF to_regclass('trading.position_overrides_one_open_publish') IS NULL THEN
        RAISE EXCEPTION 'position_overrides_one_open_publish does not exist (apply 025 first)';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'trading'
                   AND table_name = 'live_run_metadata' AND column_name = 'publish_source') THEN
        RAISE EXCEPTION 'trading.live_run_metadata has no publish_source (apply 027 first)';
    END IF;
END $$;

-- 1. The kind.
DO $$
DECLARE
    c record;
BEGIN
    -- 023 declared the CHECK inline, so its name is the server's choice: drop every CHECK on
    -- kind alone, then add the named one.
    FOR c IN
        SELECT con.conname FROM pg_constraint con
        WHERE con.conrelid = 'trading.position_overrides'::regclass AND con.contype = 'c'
          AND con.conname <> 'position_overrides_kind'
          AND pg_get_constraintdef(con.oid) ~ '^CHECK \(\(kind = ANY'
    LOOP
        EXECUTE format('ALTER TABLE trading.position_overrides DROP CONSTRAINT %I', c.conname);
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'position_overrides_kind'
                   AND conrelid = 'trading.position_overrides'::regclass) THEN
        ALTER TABLE trading.position_overrides ADD CONSTRAINT position_overrides_kind
            CHECK (kind IN ('save', 'override_request', 'override_decision', 'publish', 'rescind'));
    END IF;
END $$;

-- 2. A rescinded day may be approved again.
DROP INDEX IF EXISTS trading.position_overrides_one_publish;

-- 3. One open rescind per day.
CREATE UNIQUE INDEX IF NOT EXISTS position_overrides_one_open_rescind
    ON trading.position_overrides (portfolio_id, date)
    WHERE kind = 'rescind' AND status IN ('pending', 'running');

COMMENT ON TABLE trading.position_overrides IS
    'QT desk command log (docs/design/qt-contract.md section 4): one row per save, override request, override decision, publish and rescind. AlgoLens inserts; the engine moves status, started_at, finished_at, result and message. Never deleted. Migrations 023, 025, 029.';

COMMIT;

-- ===== algolens-api/migrations/003_screen_access.sql
-- Screen access and investor reports (Dom, 2026-10-11).
--
-- AlgoLens has three screens: member, investor and qt. An admin (role
-- exec_board) assigns each user any of them; the roles themselves are
-- unchanged. The backend reads auth.user_screen_access on every request, so a
-- grant or revoke takes effect at once. Every change is logged, append-only,
-- in auth.screen_access_log.
--
-- investor.reports holds the PDF reports and letters an admin uploads for the
-- investor screen. Reports are never deleted, only unpublished.
--
-- Backfill (keeps today's access): every general_member, team_lead and
-- exec_board user gets member; exec_board also gets qt (the desk). New
-- sign-ups get nothing until an admin grants a screen.
--
-- Grants go to svc_algolens (qt_algolens_app inherits it), when that role
-- exists. Transactional; safe to run more than once. Rollback:
-- 003_screen_access_rollback.sql.

BEGIN;

CREATE TABLE IF NOT EXISTS auth.user_screen_access (
    user_id    INTEGER     NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    screen     TEXT        NOT NULL CHECK (screen IN ('member', 'investor', 'qt')),
    granted_by TEXT        NOT NULL,
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, screen)
);

-- No foreign key: the log outlives a deleted user.
CREATE TABLE IF NOT EXISTS auth.screen_access_log (
    id       BIGSERIAL   PRIMARY KEY,
    user_id  INTEGER     NOT NULL,
    screen   TEXT        NOT NULL CHECK (screen IN ('member', 'investor', 'qt')),
    action   TEXT        NOT NULL CHECK (action IN ('grant', 'revoke')),
    by_email TEXT        NOT NULL,
    at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_screen_access_log_user
    ON auth.screen_access_log (user_id, at DESC);

CREATE SCHEMA IF NOT EXISTS investor;

CREATE TABLE IF NOT EXISTS investor.reports (
    id           BIGSERIAL   PRIMARY KEY,
    title        TEXT        NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
    kind         TEXT        NOT NULL CHECK (kind IN ('monthly', 'quarterly', 'letter', 'other')),
    period_label TEXT        NULL CHECK (period_label IS NULL OR length(period_label) <= 40),
    filename     TEXT        NOT NULL,
    content_type TEXT        NOT NULL CHECK (content_type = 'application/pdf'),
    size_bytes   INTEGER     NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 10485760),
    content      BYTEA       NOT NULL CHECK (octet_length(content) = size_bytes),
    sha256       TEXT        NOT NULL,
    uploaded_by  TEXT        NOT NULL,
    uploaded_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    published    BOOLEAN     NOT NULL DEFAULT TRUE
);
CREATE INDEX IF NOT EXISTS idx_investor_reports_uploaded
    ON investor.reports (uploaded_at DESC);

-- Backfill. role is the auth.user_role enum; compare as text.
INSERT INTO auth.user_screen_access (user_id, screen, granted_by)
SELECT id, 'member', 'migration:003' FROM auth.users
WHERE role::text IN ('general_member', 'team_lead', 'exec_board')
ON CONFLICT DO NOTHING;

INSERT INTO auth.user_screen_access (user_id, screen, granted_by)
SELECT id, 'qt', 'migration:003' FROM auth.users
WHERE role::text = 'exec_board'
ON CONFLICT DO NOTHING;

INSERT INTO auth.screen_access_log (user_id, screen, action, by_email)
SELECT a.user_id, a.screen, 'grant', 'migration:003'
FROM auth.user_screen_access a
WHERE a.granted_by = 'migration:003'
  AND NOT EXISTS (
      SELECT 1 FROM auth.screen_access_log l
      WHERE l.user_id = a.user_id AND l.screen = a.screen AND l.by_email = 'migration:003'
  );

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_algolens') THEN
        GRANT USAGE ON SCHEMA investor TO svc_algolens;
        GRANT SELECT, INSERT, DELETE ON auth.user_screen_access TO svc_algolens;
        GRANT SELECT, INSERT ON auth.screen_access_log TO svc_algolens;
        GRANT USAGE ON SEQUENCE auth.screen_access_log_id_seq TO svc_algolens;
        GRANT SELECT, INSERT, UPDATE ON investor.reports TO svc_algolens;
        GRANT USAGE ON SEQUENCE investor.reports_id_seq TO svc_algolens;
    END IF;
END $$;

COMMIT;

-- ===== sim/seed/synthetic-day.sql
-- One QT day for the synthetic fixture: enough for the desk panel to render and for the
-- clock rules (09:30 send, 10:00 cutoff) to be exercised. Not market data: no engine run can
-- succeed on it (that needs the prod snapshot).
--
--   2026-10-14  previous day: three books, published by the 10:00 fallback and sent
--   2026-10-15  the sim day: the model run's three books (qt_proposal and qt = system),
--               not published
--
-- Symbols: ZT, ZN, GC, CL, 6E (continuous .v.0), bars for 2026-10-12..14.

BEGIN;

INSERT INTO metadata.contract_metadata
    ("Databento Symbol", "IB Symbol", "Name", "Exchange", "Asset Type", "Sector", "Contract Size")
VALUES
    ('ZT', 'ZT', '2-Year T-Note', 'CBOT', 'Futures', 'Rates', '200000'),
    ('ZN', 'ZN', '10-Year T-Note', 'CBOT', 'Futures', 'Rates', '100000'),
    ('GC', 'GC', 'Gold', 'COMEX', 'Futures', 'Metals', '100'),
    ('CL', 'CL', 'Crude Oil', 'NYMEX', 'Futures', 'Energy', '1000'),
    ('6E', 'EUR', 'Euro FX', 'CME', 'Futures', 'FX', '125000');

INSERT INTO futures_data.ohlcv_1d (time, symbol, open, high, low, close, volume)
SELECT d::timestamptz, s.symbol, s.px, s.px * 1.002, s.px * 0.998, s.px * (1 + 0.001 * i), 10000
FROM (VALUES ('ZT.v.0', 103.5), ('ZN.v.0', 111.2), ('GC.v.0', 2650.0),
             ('CL.v.0', 71.4), ('6E.v.0', 1.09)) AS s(symbol, px)
CROSS JOIN LATERAL (
    SELECT g::date AS d, row_number() OVER () AS i
    FROM generate_series('2026-10-12'::date, '2026-10-14'::date, '1 day') g
) days;

-- Three books a day for the desk portfolio, the system book for its model twin.
INSERT INTO trading.positions
    (symbol, quantity, average_price, daily_unrealized_pnl, daily_realized_pnl, last_update,
     strategy_id, strategy_name, date, portfolio_id, portfolio_type)
SELECT p.symbol, p.qty, p.px, 0, 0, (b.day + time '07:00') AT TIME ZONE 'America/New_York',
       'TREND_FOLLOWING', 'TREND_FOLLOWING', b.day, b.portfolio_id, b.book
FROM (VALUES ('ZT.v.0', 8, 103.6), ('ZN.v.0', -3, 111.3), ('GC.v.0', 2, 2652.0),
             ('CL.v.0', 0, 71.5), ('6E.v.0', -4, 1.091)) AS p(symbol, qty, px)
CROSS JOIN (VALUES
    (date '2026-10-14', 'QT_CONSERVATIVE_PORTFOLIO', 'system'),
    (date '2026-10-14', 'QT_CONSERVATIVE_PORTFOLIO', 'qt_proposal'),
    (date '2026-10-14', 'QT_CONSERVATIVE_PORTFOLIO', 'qt'),
    (date '2026-10-15', 'QT_CONSERVATIVE_PORTFOLIO', 'system'),
    (date '2026-10-15', 'QT_CONSERVATIVE_PORTFOLIO', 'qt_proposal'),
    (date '2026-10-15', 'QT_CONSERVATIVE_PORTFOLIO', 'qt'),
    (date '2026-10-14', 'QT_CONSERVATIVE_MODEL_PORTFOLIO', 'system'),
    (date '2026-10-15', 'QT_CONSERVATIVE_MODEL_PORTFOLIO', 'system')
) AS b(day, portfolio_id, book);

INSERT INTO trading.equity_curve (strategy_id, timestamp, equity, portfolio_id, portfolio_type)
SELECT 'TREND_FOLLOWING', (d + time '16:00') AT TIME ZONE 'America/New_York',
       500000 + 1500 * row_number() OVER (PARTITION BY pid, book ORDER BY d), pid, book
FROM generate_series('2026-10-12'::date, '2026-10-14'::date, '1 day') d
CROSS JOIN (VALUES ('QT_CONSERVATIVE_PORTFOLIO', 'system'), ('QT_CONSERVATIVE_PORTFOLIO', 'qt'),
                   ('QT_CONSERVATIVE_MODEL_PORTFOLIO', 'system')) AS x(pid, book);

INSERT INTO trading.live_results
    (strategy_id, portfolio_id, date, current_portfolio_value, daily_return, gross_leverage,
     net_leverage, portfolio_type, created_at)
SELECT 'TREND_FOLLOWING', pid, d, 504500, 0.003, 1.2, 0.4, book,
       (d + time '07:00') AT TIME ZONE 'America/New_York'
FROM (VALUES (date '2026-10-14'), (date '2026-10-15')) AS days(d)
CROSS JOIN (VALUES ('QT_CONSERVATIVE_PORTFOLIO', 'system'), ('QT_CONSERVATIVE_PORTFOLIO', 'qt'),
                   ('QT_CONSERVATIVE_MODEL_PORTFOLIO', 'system')) AS x(pid, book);

-- 2026-10-14 published by the 10:00 fallback and sent; 2026-10-15 built at 07:00, unpublished.
INSERT INTO trading.live_run_metadata
    (date, strategy_id, portfolio_id, created_at, published_by, published_at, publish_source,
     sent_at)
VALUES
    ('2026-10-14', 'TREND_FOLLOWING', 'QT_CONSERVATIVE_PORTFOLIO',
     '2026-10-14 07:00 America/New_York', 'system:fallback-10am',
     '2026-10-14 10:00 America/New_York', 'fallback', '2026-10-14 10:00 America/New_York'),
    ('2026-10-15', 'TREND_FOLLOWING', 'QT_CONSERVATIVE_PORTFOLIO',
     '2026-10-15 07:00 America/New_York', NULL, NULL, NULL, NULL),
    ('2026-10-14', 'TREND_FOLLOWING', 'QT_CONSERVATIVE_MODEL_PORTFOLIO',
     '2026-10-14 07:00 America/New_York', 'system:model-only',
     '2026-10-14 07:00 America/New_York', 'model-only', '2026-10-14 09:30 America/New_York'),
    ('2026-10-15', 'TREND_FOLLOWING', 'QT_CONSERVATIVE_MODEL_PORTFOLIO',
     '2026-10-15 07:00 America/New_York', 'system:model-only',
     '2026-10-15 07:00 America/New_York', 'model-only', NULL);

COMMIT;
